/* ================= BIOLOGIA plus (unità 5-7) =================
   Domande aggiuntive (BIO_QB), test d'ingresso (BIO_PT) e paragrafi di spiegazione per gli argomenti b5a…b7d,
   per coprire tutte le voci del syllabus MUR 2026/27 delle unità 5, 6 e 7. Caricato dopo b8_prove_reali.js. */
BIO_QB.push(
{t:"b5a",k:"m",q:"Una cellula animale viene immersa in una soluzione ipotonica rispetto al suo citoplasma. Che cosa accade?",o:["perde acqua e raggrinzisce", "non cambia volume perché la membrana è impermeabile all'acqua", "perde ioni K⁺ per diffusione semplice e si restringe", "espelle l'acqua in eccesso con la pompa Na⁺/K⁺ senza cambiare volume", "acquista acqua per osmosi, si gonfia e può andare incontro a lisi"],a:4,s:"L'acqua si sposta verso la soluzione con più soluti (il citoplasma): nei globuli rossi si ha emolisi."},
{t:"b5a",k:"m",q:"Quale affermazione sul glicocalice è CORRETTA?",o:["è formato dalle catene di zuccheri di glicoproteine e glicolipidi esposte sul lato extracellulare", "si trova sul versante citosolico della membrana", "è costituito soprattutto da colesterolo", "è presente solo nei batteri Gram-negativi", "genera il potenziale di membrana a riposo"],a:0,s:"Gli zuccheri vengono aggiunti nel lume di reticolo e Golgi, quindi finiscono sempre sul lato esterno."},
{t:"b5a",k:"m",q:"Quale enzima riporta la fosfatidilserina nel foglietto interno della membrana plasmatica consumando ATP?",o:["scramblasi", "fosfolipasi C", "sfingomielinasi", "flippasi", "lipasi pancreatica"],a:3,s:"Le flippasi mantengono l'asimmetria; le scramblasi la annullano (per esempio nell'apoptosi)."},
{t:"b5a",k:"m",q:"Quale differenza tra proteine canale e proteine trasportatrici è corretta?",o:["i canali legano il soluto e cambiano conformazione a ogni ciclo; i trasportatori formano pori", "i canali formano un poro idrofilo e sono molto più veloci; i trasportatori legano il soluto e cambiano conformazione", "solo i canali possono fare trasporto attivo", "i trasportatori lasciano passare soltanto acqua", "i canali sono sempre aperti, i trasportatori sempre chiusi"],a:1,s:"I canali possono far passare milioni di ioni al secondo; i trasportatori (come GLUT) sono più lenti e saturabili."},
{t:"b5a",k:"m",q:"Durante la fase di depolarizzazione del potenziale d'azione di un neurone:",o:["si chiudono i canali del K⁺ e il potenziale scende a −90 mV", "la pompa Na⁺/K⁺ inverte la direzione del trasporto", "si aprono i canali del Na⁺ voltaggio-dipendenti e il Na⁺ entra nella cellula", "entra Ca²⁺ dal reticolo endoplasmatico", "esce Cl⁻ attraverso il canale CFTR"],a:2,s:"L'interno diventa positivo; poi l'apertura dei canali del K⁺ riporta il potenziale a valori negativi."},
{t:"b5a",k:"m",q:"Ordina per permeabilità decrescente attraverso un doppio strato lipidico puro:",o:["Na⁺ > glucosio > urea > O₂", "glucosio > O₂ > Na⁺ > urea", "O₂ > urea > glucosio > Na⁺", "urea > Na⁺ > O₂ > glucosio", "Na⁺ > O₂ > glucosio > urea"],a:2,s:"Passano meglio le molecole piccole e apolari, poi le piccole polari non cariche, poi le grandi polari; gli ioni quasi per niente."},
{t:"b5a",k:"m",q:"La glicoproteina P (MDR1) iperespressa da molte cellule tumorali:",o:["è un canale del cloro", "è una pompa di tipo V che acidifica i lisosomi", "è un simporto Na⁺-glucosio", "è un trasportatore ABC che espelle i farmaci usando ATP", "è un recettore accoppiato a proteine G"],a:3,s:"Causa la resistenza multipla ai chemioterapici."},
{t:"b5a",k:"c",q:"La diffusione dell'acqua attraverso una membrana semipermeabile verso la soluzione più concentrata si chiama ____.",a:["OSMOSI"],s:"Segue il gradiente di concentrazione dell'acqua."},
{t:"b5a",k:"c",q:"Le proteine canale specifiche per il passaggio rapido dell'acqua si chiamano ____.",a:["ACQUAPORINE", "AQUAPORINE", "ACQUAPORINA"],s:"Abbondanti nel rene e nei globuli rossi."},
{t:"b5a",k:"c",q:"Il ritorno del potenziale verso valori negativi, dovuto all'uscita di K⁺, si chiama ____.",a:["RIPOLARIZZAZIONE"],s:"Segue la depolarizzazione dovuta all'ingresso di Na⁺."},
{t:"b5b",k:"m",q:"Il recettore dei glucocorticoidi, in assenza dell'ormone, si trova nel citosol legato a:",o:["IκB, che lo fa degradare", "un complesso con la chaperon Hsp90, che ne tiene nascosta la NLS", "importina β e Ran-GTP", "calnexina nella membrana del reticolo", "SRP, che lo porta al reticolo"],a:1,s:"Il legame del cortisolo scioglie il complesso, espone la NLS e il recettore entra nel nucleo."},
{t:"b5b",k:"m",q:"Come esce dal nucleo la maggior parte degli mRNA maturi?",o:["per diffusione attraverso la membrana nucleare", "dentro vescicole COPII", "solo durante la mitosi, quando l'involucro si rompe", "legati a un'importina che li accompagna nel citosol", "come ribonucleoproteine riconosciute dal recettore NXF1 (TAP), in modo indipendente da Ran"],a:4,s:"Gli mRNA che contengono ancora introni vengono trattenuti nel nucleo: è un controllo di qualità."},
{t:"b5b",k:"m",q:"Le subunità ribosomiali vengono assemblate:",o:["nel nucleolo, con proteine importate dal citosol, e poi esportate attraverso i pori", "nel citosol, a partire da rRNA esportati singolarmente", "nel lume del reticolo ruvido", "nella matrice mitocondriale", "nelle cisterne del Golgi"],a:0,s:"L'rRNA si trascrive e matura nel nucleolo."},
{t:"b5b",k:"m",q:"Che cosa succede se si inattiva RanGAP nel citosol?",o:["le importine legano meglio la NLS", "i pori nucleari si chiudono definitivamente", "l'involucro nucleare si frammenta", "Ran-GTP si accumula anche nel citosol e il trasporto nucleare perde la sua direzionalità", "Ran-GTP scompare dal nucleo"],a:3,s:"Senza RanGAP il GTP non viene idrolizzato nel citosol: le esportine non rilasciano il carico e le importine non lo legano."},
{t:"b5b",k:"m",q:"Quale di queste strutture è un condensato nucleare privo di membrana?",o:["il lisosoma", "l'endosoma precoce", "il nucleolo", "il perossisoma", "la vescicola COPI"],a:2,s:"Come i corpi di Cajal e gli speckle, si forma per separazione di fase di proteine e RNA."},
{t:"b5b",k:"m",q:"La membrana esterna dell'involucro nucleare:",o:["è continua con il reticolo endoplasmatico e porta ribosomi", "è priva di pori", "contiene le lamine sul lato citosolico", "è identica alla membrana plasmatica", "è separata dalla membrana interna da uno spazio pieno di cromatina"],a:0,s:"Lo spazio tra le due membrane è in continuità con il lume del reticolo."},
{t:"b5b",k:"m",q:"Dal punto di vista topologico, il lume del reticolo endoplasmatico è equivalente:",o:["al citosol", "all'ambiente extracellulare (come i lumi di Golgi, endosomi e lisosomi)", "alla matrice mitocondriale", "al nucleoplasma", "allo spazio tra i due foglietti della membrana"],a:1,s:"Per questo la faccia luminale delle membrane diventa, dopo la fusione, la faccia esterna della cellula."},
{t:"b5b",k:"c",q:"Le circa 30 proteine diverse che formano il complesso del poro nucleare si chiamano ____.",a:["NUCLEOPORINE", "NUCLEOPORINA"],s:"Alcune hanno le ripetizioni FG."},
{t:"b5b",k:"c",q:"Il segnale di esportazione nucleare, ricco di leucine, è indicato con la sigla ____.",a:["NES"],s:"È riconosciuto dalle esportine insieme a Ran-GTP."},
{t:"b5b",k:"c",q:"La piccola GTPasi il cui gradiente tra nucleo e citosol dà la direzione al trasporto nucleare si chiama ____.",a:["RAN"],s:"Ran-GTP è alto nel nucleo, Ran-GDP nel citosol."},
{t:"b5c",k:"m",q:"Quale enzima della glicolisi è il principale punto di regolazione, inibito da ATP e citrato?",o:["esochinasi", "aldolasi", "lattato deidrogenasi", "citrato sintasi", "fosfofruttochinasi-1"],a:4,s:"Catalizza la seconda fosforilazione, il passaggio che impegna lo zucchero nella glicolisi."},
{t:"b5c",k:"m",q:"In carenza di O₂ il muscolo riduce il piruvato a lattato. A che cosa serve?",o:["a produrre altri 30 ATP", "a rigenerare il NAD⁺ necessario perché la glicolisi continui", "a liberare CO₂", "a sintetizzare glucosio nel muscolo", "ad attivare la catena respiratoria"],a:1,s:"Senza NAD⁺ la gliceraldeide-3-fosfato deidrogenasi si fermerebbe."},
{t:"b5c",k:"m",q:"L'accettore finale degli elettroni nella catena respiratoria è:",o:["il NAD⁺", "la CO₂", "l'O₂, che si riduce ad acqua", "il FAD", "il citocromo c"],a:2,s:"Il complesso IV trasferisce gli elettroni all'ossigeno."},
{t:"b5c",k:"m",q:"I complessi della catena respiratoria pompano protoni:",o:["dalla matrice allo spazio intermembrana", "dallo spazio intermembrana alla matrice", "dal citosol alla matrice", "dalla matrice al citosol attraverso TOM", "dal lume del reticolo al mitocondrio"],a:0,s:"I protoni rientrano poi nella matrice attraverso l'ATP sintasi."},
{t:"b5c",k:"m",q:"Quale proteina media la fusione della membrana mitocondriale INTERNA?",o:["DRP1", "mitofusina 2", "TOM20", "Bax", "OPA1"],a:4,s:"Le mitofusine fondono la membrana esterna; DRP1 media la fissione."},
{t:"b5c",k:"m",q:"Nel codice genetico mitocondriale umano il codone UGA:",o:["codifica metionina", "è il codone di inizio", "codifica selenocisteina come nel nucleo", "codifica triptofano invece di essere un segnale di stop", "non viene mai letto"],a:3,s:"È una delle differenze rispetto al codice «universale»."},
{t:"b5c",k:"m",q:"Il DNA mitocondriale umano viene trascritto:",o:["gene per gene, ciascuno con il proprio promotore e la TATA box", "in lunghi trascritti policistronici da entrambi i filamenti, poi tagliati in corrispondenza dei tRNA", "dall'RNA polimerasi II nucleare", "solo durante la mitosi", "solo nelle cellule germinali femminili"],a:1,s:"I tRNA fanno da «punteggiatura» tra un gene e l'altro."},
{t:"b5c",k:"m",q:"Quante molecole di CO₂ si liberano in tutto dall'ossidazione completa di una molecola di glucosio?",o:["2", "4", "6", "12", "32"],a:2,s:"2 dalla piruvato deidrogenasi e 4 dal ciclo di Krebs (2 per ciascun acetil-CoA)."},
{t:"b5c",k:"c",q:"Il complesso che inserisce le proteine a barile β nella membrana mitocondriale esterna si chiama ____ (sigla).",a:["SAM"],s:"Riceve le proteine dopo il passaggio attraverso TOM."},
{t:"b5c",k:"c",q:"Nella glicolisi ogni molecola di glucosio fornisce un guadagno netto di ____ ATP (numero).",a:["2", "DUE"],s:"Se ne spendono 2 e se ne producono 4."},
{t:"b5c",k:"c",q:"La GTPasi citosolica che, reclutata sulla membrana esterna, strozza e divide i mitocondri si chiama ____ (sigla).",a:["DRP1", "DRP-1"],s:"La fissione serve anche a isolare le parti danneggiate per la mitofagia."},
{t:"b5c",k:"c",q:"La presenza nella stessa cellula di copie normali e mutate del DNA mitocondriale si chiama ____.",a:["ETEROPLASMIA"],s:"La malattia compare quando le copie mutate superano una soglia."},
{t:"b5d",k:"m",q:"Il segnale PTS1 che indirizza le proteine alla matrice dei perossisomi è:",o:["una presequenza N-terminale con cariche positive", "la sequenza KDEL", "un residuo di mannosio-6-fosfato", "una sequenza ricca di leucine", "la sequenza SKL all'estremità C-terminale"],a:4,s:"Il PTS2, meno comune, si trova vicino all'N-terminale."},
{t:"b5d",k:"m",q:"A differenza dei mitocondri, i perossisomi importano le proteine della matrice:",o:["srotolate e durante la traduzione", "solo se codificate dal loro DNA", "attraverso il complesso TOM", "già ripiegate, anche sotto forma di oligomeri", "con vescicole COPII dal Golgi"],a:3,s:"È una delle peculiarità del trasporto ai perossisomi."},
{t:"b5d",k:"m",q:"Quale di queste funzioni NON è svolta dai perossisomi?",o:["sintesi di ATP con un'ATP sintasi", "β-ossidazione degli acidi grassi a catena molto lunga", "prime tappe della sintesi dei plasmalogeni", "decomposizione dell'H₂O₂ con la catalasi", "ossidazione di parte dell'etanolo nel fegato"],a:0,s:"I perossisomi non hanno catena respiratoria né ATP sintasi."},
{t:"b5d",k:"m",q:"Il recettore citosolico che riconosce il segnale PTS1 e accompagna la proteina al perossisoma è:",o:["SRP", "importina α", "TOM20", "PEX5", "PEX3"],a:3,s:"PEX7 riconosce invece il PTS2; PEX3 sta sulla membrana."},
{t:"b5d",k:"m",q:"Nelle cellule di un paziente con sindrome di Zellweger le proteine della matrice perossisomiale:",o:["vengono importate normalmente ma sono inattive", "finiscono nei mitocondri", "vengono secrete all'esterno", "si accumulano nel nucleo", "restano nel citosol e vengono degradate, mentre si formano «fantasmi» di membrana vuoti"],a:4,s:"Il difetto riguarda le perossine che servono all'importazione."},
{t:"b5d",k:"m",q:"Quale reazione è catalizzata dalla catalasi?",o:["RH₂ + O₂ → R + H₂O₂", "glucosio → 2 piruvato", "2 H₂O₂ → 2 H₂O + O₂", "ATP → ADP + Pi", "NADH → NAD⁺ + H⁺ + 2 e⁻"],a:2,s:"Elimina l'acqua ossigenata prodotta dalle ossidasi."},
{t:"b5d",k:"m",q:"Un bambino con sindrome di Zellweger ha gravi difetti della mielina. Quale funzione perossisomiale mancante lo spiega meglio?",o:["la sintesi dei plasmalogeni", "la sintesi del glicogeno", "la glicolisi", "la sintesi del colesterolo nel reticolo", "il ciclo dell'urea"],a:0,s:"I plasmalogeni sono fosfolipidi abbondanti nella mielina; la loro sintesi inizia nei perossisomi."},
{t:"b5d",k:"m",q:"Le proteine della membrana perossisomiale vengono inserite grazie a:",o:["SRP e il traslocone Sec61", "PEX19, recettore citosolico, e PEX3, sulla membrana", "il complesso TIM22", "vescicole rivestite di clatrina", "calnexina e calreticulina"],a:1,s:"È una via diversa da quella delle proteine della matrice (PEX5 e PEX7)."},
{t:"b5d",k:"c",q:"L'enzima perossisomiale che decompone l'acqua ossigenata in acqua e ossigeno è la ____.",a:["CATALASI"],s:"Protegge la cellula dall'H₂O₂."},
{t:"b5d",k:"c",q:"Un perossisoma è delimitato da ____ membrana (numero).",a:["1", "UNA", "UNO", "UNA SOLA"],s:"A differenza dei mitocondri, che ne hanno due."},
{t:"b5d",k:"c",q:"I fosfolipidi abbondanti nella mielina, la cui sintesi inizia nei perossisomi, si chiamano ____.",a:["PLASMALOGENI", "PLASMALOGENO"],s:"Mancano nella sindrome di Zellweger."},
{t:"b5d",k:"c",q:"I perossisomi possono nascere ex novo da vescicole che gemmano dal reticolo ____.",a:["ENDOPLASMATICO", "ENDOPLASMICO"],s:"Oppure dividendosi da perossisomi preesistenti."},
{t:"b5e",k:"m",q:"Che cosa fa la peptidasi del segnale?",o:["aggiunge l'oligosaccaride sull'asparagina", "porta il ribosoma al reticolo", "degrada nel citosol le proteine mal ripiegate", "taglia il peptide segnale dal lato del lume del reticolo", "taglia SREBP nel Golgi"],a:3,s:"Il segnale non serve più dopo l'ingresso della catena."},
{t:"b5e",k:"m",q:"Nelle plasmacellule le catene pesanti delle immunoglobuline non ancora assemblate:",o:["vengono subito secrete", "vanno ai lisosomi tramite il mannosio-6-fosfato", "restano trattenute nel reticolo (da BiP e dalle lectine chaperon) finché non si uniscono alle catene leggere", "vengono importate nel nucleo", "vengono glicosilate nel citosol"],a:2,s:"Esempio classico di controllo di qualità del reticolo: escono solo anticorpi completi."},
{t:"b5e",k:"m",q:"Calnexina e calreticulina riconoscono le glicoproteine che portano:",o:["un residuo di mannosio-6-fosfato", "la sequenza KDEL", "tre residui di acido sialico", "una NLS", "un solo glucosio terminale sull'oligosaccaride legato all'asparagina"],a:4,s:"Le glucosidasi tolgono due dei tre glucosi; se la proteina è ancora mal ripiegata un enzima le riaggiunge il glucosio."},
{t:"b5e",k:"m",q:"Quale dei tre sensori della risposta UPR viaggia fino al Golgi, dove viene tagliato liberando un fattore di trascrizione?",o:["IRE1", "ATF6", "PERK", "BiP", "Sec61"],a:1,s:"Viene tagliato dalle stesse proteasi che attivano SREBP."},
{t:"b5e",k:"m",q:"Le proteine residenti nel lume del reticolo che sfuggono verso il Golgi vengono riportate indietro grazie a:",o:["la sequenza KDEL, riconosciuta da un recettore, e vescicole COPI", "la sequenza SKL e le perossine", "il mannosio-6-fosfato", "vescicole di clatrina verso la membrana plasmatica", "il traslocone Sec61"],a:0,s:"Così BiP e la disolfuro isomerasi restano nel reticolo."},
{t:"b5e",k:"m",q:"La N-glicosilazione nel reticolo avviene:",o:["sul gruppo OH di serina e treonina nel Golgi", "trasferendo in blocco un oligosaccaride preformato, portato dal dolicolo, su un'asparagina", "aggiungendo uno zucchero alla volta nel citosol", "sul C-terminale di tutte le proteine", "solo sulle proteine nucleari"],a:1,s:"L'O-glicosilazione su serina e treonina avviene invece soprattutto nel Golgi."},
{t:"b5e",k:"m",q:"Quale chaperon citosolica lega le catene nascenti mentre escono dal ribosoma, impedendo ripiegamenti scorretti?",o:["calreticulina", "clatrina", "catalasi", "caspasi 3", "Hsp70"],a:4,s:"Mantiene anche srotolate le proteine destinate ai mitocondri."},
{t:"b5e",k:"m",q:"La rete cis del Golgi:",o:["riceve le vescicole COPII provenienti dal reticolo", "è il lato di uscita verso la membrana plasmatica", "è il compartimento in cui si formano i lisosomi maturi", "è ricoperta di ribosomi", "coincide con l'involucro nucleare"],a:0,s:"Il carico procede poi verso le cisterne mediali e la rete trans."},
{t:"b5e",k:"c",q:"Il canale proteico del reticolo attraverso cui passa la catena nascente si chiama ____ (o Sec61).",a:["TRASLOCONE"],s:"Si apre quando il ribosoma vi si aggancia."},
{t:"b5e",k:"c",q:"Il sistema che riporta nel citosol le proteine mal ripiegate del reticolo per farle degradare dal proteasoma si chiama ____ (sigla).",a:["ERAD"],s:"È quello che elimina il CFTR ΔF508 nella fibrosi cistica."},
{t:"b5e",k:"c",q:"La risposta allo stress del reticolo dovuta all'accumulo di proteine mal ripiegate si chiama ____ (sigla).",a:["UPR"],s:"Sensori IRE1, PERK e ATF6."},
{t:"b5f",k:"m",q:"Qual è la differenza principale tra endocitosi in fase fluida ed endocitosi mediata da recettori?",o:["la prima richiede sempre la clatrina, la seconda mai", "la prima riguarda solo particelle più grandi di un batterio", "la seconda avviene solo nei macrofagi", "la prima ingloba in modo non selettivo liquido e soluti; la seconda concentra molecole specifiche legate a recettori", "la prima consuma ATP, la seconda no"],a:3,s:"L'endocitosi mediata da recettori può concentrare il ligando di oltre mille volte."},
{t:"b5f",k:"m",q:"Quale destino distingue il recettore dell'EGF da quello delle LDL dopo l'endocitosi?",o:["il recettore dell'EGF viene riciclato, quello delle LDL degradato", "entrambi i recettori vengono degradati nei lisosomi", "il recettore dell'EGF viene ubiquitinato, finisce nei corpi multivescicolari ed è degradato; quello delle LDL torna in superficie", "entrambi restano per sempre nell'endosoma precoce", "il recettore dell'EGF viene trasportato nel nucleo"],a:2,s:"La degradazione del recettore dell'EGF spegne il segnale (down-regolazione)."},
{t:"b5f",k:"m",q:"I corpi multivescicolari si formano quando:",o:["il Golgi si frammenta in mitosi", "la membrana dell'endosoma gemma verso l'interno, sequestrando proteine ubiquitinate (complessi ESCRT)", "i lisosomi si fondono con la membrana plasmatica", "il reticolo produce vescicole COPII", "l'autofagosoma si chiude attorno a un mitocondrio"],a:1,s:"Le vescicole interne vengono poi digerite nel lisosoma."},
{t:"b5f",k:"m",q:"La transcitosi delle IgA nell'epitelio intestinale:",o:["porta le IgA dal lato basolaterale al lume, legate al recettore delle immunoglobuline polimeriche", "porta le IgA dal lume intestinale al sangue", "avviene attraverso le giunzioni gap", "richiede che i macrofagi fagocitino le IgA", "termina con la degradazione delle IgA nei lisosomi"],a:0,s:"Sul lato apicale il recettore viene tagliato e un suo pezzo (componente secretoria) resta legato alle IgA."},
{t:"b5f",k:"m",q:"Nella malattia a cellule I manca il marcatore mannosio-6-fosfato. Che cosa accade alle idrolasi lisosomiali?",o:["si accumulano nel nucleo", "vengono degradate nel reticolo dall'ERAD", "funzionano meglio perché restano nel Golgi", "vengono secrete all'esterno e i lisosomi restano pieni di materiale non digerito", "vengono importate nei perossisomi"],a:3,s:"Senza M6P il recettore del trans-Golgi non le riconosce e seguono la via costitutiva."},
{t:"b5f",k:"m",q:"Nella malattia di Tay-Sachs si accumula nei lisosomi dei neuroni:",o:["glicogeno, per difetto dell'α-glucosidasi acida", "colesterolo libero", "il ganglioside GM2, per difetto dell'esosaminidasi A", "acidi grassi a catena molto lunga", "ferro legato alla transferrina"],a:2,s:"È una malattia da accumulo lisosomiale autosomica recessiva."},
{t:"b5f",k:"m",q:"La macroautofagia si distingue dall'autofagia mediata da chaperon perché:",o:["trasporta singole proteine con il motivo KFERQ attraverso la proteina LAMP-2A", "avviene soltanto nei batteri", "non coinvolge i lisosomi", "degrada esclusivamente DNA", "sequestra porzioni di citoplasma in un autofagosoma a doppia membrana che poi si fonde con il lisosoma"],a:4,s:"Nella microautofagia è il lisosoma stesso a inglobare direttamente il materiale."},
{t:"b5f",k:"m",q:"Quali proteine, mutate in forme familiari di malattia di Parkinson, segnalano i mitocondri danneggiati per la mitofagia?",o:["Rab5 e Rab7", "clatrina e AP2", "PINK1 e Parkin", "Bcl-2 e Bcl-xL", "dinamina e caveolina"],a:2,s:"PINK1 si accumula sui mitocondri depolarizzati e recluta l'ubiquitina ligasi Parkin."},
{t:"b5f",k:"m",q:"Il fosfoinositide tipico della membrana plasmatica, che recluta gli adattatori della clatrina, è:",o:["PI3P", "PI4P", "cardiolipina", "fosfatidilcolina", "PI(4,5)P₂"],a:4,s:"PI3P marca gli endosomi precoci, PI4P il Golgi."},
{t:"b5f",k:"m",q:"Quale GTPasi Rab identifica tipicamente gli endosomi precoci?",o:["Rab7", "Ran", "Ras", "Rab5", "Rho"],a:3,s:"Rab7 marca gli endosomi tardivi, Rab11 quelli di riciclo."},
{t:"b5f",k:"c",q:"L'acidificazione del lisosoma a pH circa 5 è dovuta a una pompa protonica di tipo ____ (una lettera).",a:["V"],s:"ATPasi di tipo V, come nelle vescicole sinaptiche."},
{t:"b5f",k:"c",q:"L'ingestione di particelle grandi, come batteri o cellule apoptotiche, da parte di macrofagi e neutrofili si chiama ____.",a:["FAGOCITOSI"],s:"Il fagosoma si fonde poi con i lisosomi."},
{t:"b5f",k:"c",q:"La struttura a doppia membrana che sequestra porzioni di citoplasma nella macroautofagia si chiama ____.",a:["AUTOFAGOSOMA"],s:"Fondendosi con il lisosoma forma l'autolisosoma."},
{t:"b5f",k:"c",q:"L'ATPasi che separa i complessi SNARE dopo la fusione delle membrane si indica con la sigla ____.",a:["NSF"],s:"Agisce insieme alle proteine SNAP."},
{t:"b5g",k:"m",q:"Il complesso che nuclea i microtubuli nel centrosoma è:",o:["il complesso Arp2/3", "il γTuRC, anello di γ-tubulina", "la formina", "il complesso NDC80", "la coesina"],a:1,s:"L'estremità − resta ancorata al γTuRC."},
{t:"b5g",k:"m",q:"Un microtubulo va incontro a «catastrofe» (rapido accorciamento) quando:",o:["la sua estremità + perde il cappuccio di tubulina-GTP", "lega troppa tubulina-GTP", "viene percorso da una dineina", "viene stabilizzato dal taxolo", "l'actina idrolizza il suo ATP"],a:0,s:"La tubulina-GDP nel reticolo del microtubulo è instabile: è l'instabilità dinamica."},
{t:"b5g",k:"m",q:"Quale proteina associata ai microtubuli NON è un motore?",o:["chinesina-1", "tau", "dineina citoplasmatica", "dineina dell'assonema", "chinesina-5"],a:1,s:"Tau è una MAP non motrice che stabilizza i microtubuli (alterata nell'Alzheimer)."},
{t:"b5g",k:"m",q:"Mutazioni di LIS1, regolatore della dineina citoplasmatica, causano lissencefalia perché:",o:["le ciglia respiratorie diventano immobili", "la mielina non si forma", "l'actina non polimerizza", "i neuroni migrano male durante lo sviluppo della corteccia", "i desmosomi si rompono"],a:3,s:"La corteccia risulta liscia, senza circonvoluzioni."},
{t:"b5g",k:"m",q:"Nella discinesia ciliare primaria (sindrome di Kartagener) le dineine dell'assonema sono difettose. Quale quadro è tipico?",o:["distrofia muscolare progressiva", "anemia emolitica", "infezioni respiratorie ricorrenti, infertilità maschile e a volte situs inversus", "diabete di tipo 1", "bolle cutanee per traumi minimi"],a:2,s:"Le ciglia non muovono il muco, gli spermatozoi non nuotano e nell'embrione la lateralità è casuale."},
{t:"b5g",k:"m",q:"L'actina-G si aggiunge al filamento soprattutto:",o:["all'estremità + (barbed), legata ad ATP", "all'estremità −, legata a GTP", "in qualsiasi punto, senza nucleotide", "solo all'interno del nucleo", "grazie alla dineina"],a:0,s:"Nel filamento l'ATP viene idrolizzato ad ADP."},
{t:"b5g",k:"m",q:"Durante la contrazione del sarcomero:",o:["i filamenti di actina e di miosina si accorciano", "la banda A si accorcia", "i microtubuli spingono le linee Z", "la distrofina si contrae", "i filamenti sottili di actina scorrono su quelli spessi di miosina II e le linee Z si avvicinano"],a:4,s:"Teoria dello scorrimento: si restringono banda I e zona H, non la banda A."},
{t:"b5g",k:"m",q:"Un neutrofilo segue un gradiente di fMLP. Dove è attiva soprattutto Rac?",o:["sul fronte, dove forma il lamellipodio", "sul retro, dove contrae l'actomiosina", "nel nucleo", "in modo uniforme in tutta la cellula", "sui microtubuli astrali"],a:0,s:"Al retro domina Rho, che contrae la coda."},
{t:"b5g",k:"m",q:"Perché i filamenti intermedi non sono polari?",o:["perché sono fatti di tubulina legata a GTP", "perché i monomeri legano ATP", "perché i dimeri a coiled-coil si associano in tetrameri antiparalleli", "perché nascono dal γTuRC", "perché sono formati da monomeri globulari"],a:2,s:"Per questo nessun motore può muoversi su di essi."},
{t:"b5g",k:"m",q:"Le nesprine e le proteine SUN (complesso LINC):",o:["formano le giunzioni comunicanti", "nucleano i filamenti di actina", "sono motori dei microtubuli", "collegano il citoscheletro alla lamina nucleare attraverso l'involucro nucleare", "tagliano la lamina all'inizio della mitosi"],a:3,s:"Trasmettono forze meccaniche fino al nucleo."},
{t:"b5g",k:"m",q:"La plectina:",o:["è una catena leggera della miosina", "collega tra loro filamenti intermedi, microtubuli e actina", "è la tubulina del centrosoma", "è una caderina desmosomiale", "è un canale ionico"],a:1,s:"È una proteina «ponte» tra i diversi elementi del citoscheletro."},
{t:"b5g",k:"c",q:"Il fenomeno per cui un filamento di actina aggiunge monomeri all'estremità + e li perde dalla − mantenendo la lunghezza costante si chiama ____ (termine inglese).",a:["TREADMILLING"],s:"Dipende dall'idrolisi dell'ATP nel filamento."},
{t:"b5g",k:"c",q:"Le chinesine trasportano i carichi verso l'estremità ____ dei microtubuli.",a:["PIU", "PIÙ", "+", "POSITIVA"],s:"Cioè, in genere, dal centro verso la periferia."},
{t:"b5g",k:"c",q:"I filamenti intermedi della lamina nucleare sono formati dalle ____ (tipi A, B e C).",a:["LAMINE", "LAMINA"],s:"Mutate nella progeria."},
{t:"b5g",k:"c",q:"Le ciglia primarie, non mobili, hanno un assonema di tipo 9 + ____ (numero).",a:["0", "ZERO"],s:"Manca la coppia centrale; funzionano da antenne sensoriali."},
{t:"b6a",k:"m",q:"La sequenza della fibronectina riconosciuta da molte integrine è:",o:["KDEL", "SKL", "KFERQ", "TTAGGG", "RGD (arginina-glicina-aspartato)"],a:4,s:"Farmaci anti-aggreganti imitano questa sequenza per bloccare le integrine delle piastrine."},
{t:"b6a",k:"m",q:"Il collagene fibrillare ha una struttura:",o:["a tripla elica di catene con la ripetizione Gly-X-Y, ricca di prolina", "a doppia elica antiparallela", "a foglietti β globulari", "a filamenti di actina", "a 13 protofilamenti"],a:0,s:"L'idrossilazione della prolina richiede vitamina C (scorbuto)."},
{t:"b6a",k:"m",q:"I TIMP:",o:["sono recettori della fibronectina", "inibiscono le metalloproteinasi della matrice", "degradano il collagene", "sono glicosamminoglicani solfatati", "formano le adesioni focali"],a:1,s:"L'equilibrio MMP/TIMP regola il rimodellamento della matrice."},
{t:"b6a",k:"m",q:"Nelle adesioni focali le integrine sono collegate all'actina tramite:",o:["cheratine", "connessine", "lamine", "proteine SNARE", "talina e vinculina"],a:4,s:"Negli emidesmosomi invece si collegano ai filamenti intermedi."},
{t:"b6a",k:"m",q:"Meccanotrasduzione: una cellula coltivata su una matrice rigida rispetto a una morbida:",o:["non percepisce alcuna differenza", "perde tutte le integrine", "smette di formare adesioni focali", "aumenta la tensione dell'actomiosina e attiva fattori come YAP/TAZ che entrano nel nucleo", "si divide senza bisogno di ancoraggio"],a:3,s:"Le forze vengono trasformate in segnali biochimici che cambiano l'espressione genica."},
{t:"b6a",k:"m",q:"Perché i glicosamminoglicani formano gel idratati che resistono alla compressione?",o:["sono molecole idrofobiche", "formano ponti disolfuro con il collagene", "sono molto carichi negativamente e richiamano cationi e acqua", "sono rigidi come l'idrossiapatite", "contengono fosfolipidi"],a:2,s:"Per questo la cartilagine resiste al carico."},
{t:"b6a",k:"m",q:"L'assemblaggio della fibronectina in fibrille nella matrice:",o:["avviene spontaneamente nel plasma", "richiede la tensione esercitata dalle cellule attraverso le integrine", "avviene nel nucleo", "richiede le giunzioni gap", "è catalizzato dalle metalloproteinasi"],a:1,s:"Lo stiramento espone siti nascosti che permettono alle molecole di unirsi."},
{t:"b6a",k:"c",q:"Le glicoproteine della lamina basale che, con il collagene IV, legano le integrine degli epiteli sono le ____.",a:["LAMININE", "LAMININA"],s:"La lamina basale contiene anche il perlecano."},
{t:"b6a",k:"c",q:"Le integrine sono eterodimeri formati da una subunità α e una subunità ____.",a:["BETA", "Β"],s:"Diverse combinazioni αβ legano componenti diversi della matrice."},
{t:"b6a",k:"c",q:"Le metalloproteinasi della matrice hanno nel sito attivo uno ione ____.",a:["ZINCO", "ZN", "ZN2+"],s:"Da qui il nome «metallo»-proteinasi."},
{t:"b6b",k:"m",q:"Le giunzioni occludenti, oltre a sigillare lo spazio tra le cellule:",o:["collegano i filamenti intermedi alla lamina basale", "fanno passare ioni tra i citoplasmi", "legano la fibronectina", "impediscono la diffusione laterale delle proteine tra membrana apicale e basolaterale", "producono il glicocalice"],a:3,s:"È la funzione di «recinto» che mantiene la polarità dell'epitelio."},
{t:"b6b",k:"m",q:"Nelle giunzioni aderenti le caderine si collegano all'actina tramite:",o:["le catenine", "la plectina", "le connessine", "le claudine", "le lamine"],a:0,s:"La β-catenina partecipa anche alla via di segnalazione Wnt."},
{t:"b6b",k:"m",q:"Gli emidesmosomi collegano:",o:["due cellule epiteliali tramite caderine e actina", "due neuroni in una sinapsi", "i citoplasmi di due cellule vicine", "il nucleo alla membrana plasmatica", "la cellula epiteliale alla lamina basale, tramite integrine e filamenti intermedi"],a:4,s:"I desmosomi collegano invece cellula a cellula."},
{t:"b6b",k:"m",q:"Cellule epiteliali messe in un mezzo senza Ca²⁺ si staccano tra loro. Quali molecole hanno smesso di funzionare?",o:["le NCAM", "le connessine", "le caderine", "le acquaporine", "le selectine legate al glicocalice"],a:2,s:"Le caderine richiedono Ca²⁺ per mantenere la conformazione adesiva."},
{t:"b6b",k:"m",q:"Le giunzioni comunicanti permettono il passaggio tra cellule vicine di:",o:["proteine e RNA messaggeri", "organelli interi", "soltanto acqua", "ioni e piccole molecole come cAMP e Ca²⁺ (sotto circa 1 kDa)", "nessuna molecola: servono solo all'adesione"],a:3,s:"Nel cuore propagano l'impulso elettrico."},
{t:"b6b",k:"m",q:"Si mescolano cellule che esprimono E-caderina con cellule che esprimono N-caderina. Che cosa si osserva?",o:["formano un mosaico casuale e stabile", "si fondono in un sincizio", "muoiono per apoptosi", "si trasformano tutte in fibroblasti", "le cellule si separano in gruppi che esprimono la stessa caderina"],a:4,s:"L'adesione omofila permette il riconoscimento e la formazione dei tessuti."},
{t:"b6b",k:"m",q:"Le CAM della superfamiglia delle immunoglobuline (come NCAM) si distinguono dalle caderine perché:",o:["sono enzimi", "si trovano solo nei batteri", "non hanno bisogno del Ca²⁺", "formano canali tra cellule", "legano i filamenti intermedi negli emidesmosomi"],a:2,s:"Le caderine sono invece Ca²⁺-dipendenti."},
{t:"b6b",k:"m",q:"Nel pemfigoide bolloso gli anticorpi colpiscono componenti degli emidesmosomi. Dove si forma la bolla?",o:["tra epidermide e derma, sotto lo strato basale", "tra i cheratinociti dello strato spinoso", "dentro il nucleo dei cheratinociti", "nella parete dei vasi", "nel fegato"],a:0,s:"Nel pemfigo (desmosomi) la bolla è invece dentro l'epidermide."},
{t:"b6b",k:"c",q:"Le principali proteine transmembrana delle giunzioni occludenti sono l'occludina e le ____.",a:["CLAUDINE", "CLAUDINA"],s:"Determinano anche quali ioni possono passare tra le cellule."},
{t:"b6b",k:"c",q:"Ogni connessone (emicanale) è formato da ____ connessine (numero).",a:["6", "SEI"],s:"Due connessoni affacciati formano il canale completo."},
{t:"b6b",k:"c",q:"La perdita della E-____ favorisce il distacco delle cellule epiteliali tumorali e le metastasi.",a:["CADERINA"],s:"Accompagna la transizione epitelio-mesenchima."},
{t:"b6c",k:"m",q:"Le piccole GTPasi monomeriche (Ras, Rho, Rab, Ran, Arf) vengono attivate da:",o:["GAP, che accelerano l'idrolisi del GTP", "GEF, che fanno scambiare il GDP con il GTP", "chinasi che le fosforilano sulle tirosine", "proteasi che le tagliano", "il cAMP prodotto dall'adenilato ciclasi"],a:1,s:"Le GAP le spengono."},
{t:"b6c",k:"m",q:"Nella neurofibromatosi di tipo 1 manca la neurofibromina, una GAP di Ras. Conseguenza?",o:["Ras resta più a lungo legato al GTP e favorisce la proliferazione", "Ras viene spento in modo permanente", "SOS non può più legare Grb2", "la PKA viene inibita", "le cellule vanno tutte in apoptosi"],a:0,s:"Perdere una GAP equivale ad attivare la GTPasi."},
{t:"b6c",k:"m",q:"Nella visione, la luce attiva la rodopsina, che attiva la transducina e poi una fosfodiesterasi. Risultato:",o:["il cGMP aumenta e i canali si aprono", "il cAMP aumenta e la cellula si depolarizza", "il cGMP diminuisce, i canali cationici si chiudono e il bastoncello si iperpolarizza", "si apre un canale del Cl⁻", "aumenta il rilascio di glutammato"],a:2,s:"Al buio i canali sono aperti dal cGMP e il fotorecettore è depolarizzato."},
{t:"b6c",k:"m",q:"La rodopsina attivata viene spenta tramite:",o:["degradazione immediata nel proteasoma", "fosforilazione da parte della rodopsina chinasi e legame dell'arrestina", "endocitosi tramite caveole", "taglio da parte delle caspasi", "legame con Ran-GTP"],a:1,s:"È un esempio di desensitizzazione recettoriale."},
{t:"b6c",k:"m",q:"Il recettore dell'insulina, a differenza di quello dell'EGF:",o:["non ha attività tirosin-chinasica", "è un recettore intracellulare", "è accoppiato a proteine G trimeriche", "è già un dimero α₂β₂ unito da ponti disolfuro anche senza ligando", "è un canale ionico"],a:3,s:"Il recettore dell'EGF dimerizza solo dopo aver legato il fattore di crescita."},
{t:"b6c",k:"m",q:"Nel muscolo e nel tessuto adiposo l'insulina porta il trasportatore GLUT4 in membrana attraverso la via:",o:["Gq → fosfolipasi C → IP₃", "Gs → adenilato ciclasi → cAMP → PKA", "NO → guanilato ciclasi → cGMP", "recettore nucleare → trascrizione di GLUT4", "IRS → PI3K → PIP₃ → Akt"],a:4,s:"Le proteine IRS sono i substrati fosforilati dal recettore."},
{t:"b6c",k:"m",q:"La fosfatasi PTEN, un oncosoppressore:",o:["attiva Ras scambiando il GDP", "fosforila Rb", "produce cAMP", "degrada il cGMP", "rimuove il fosfato in posizione 3 del PIP₃ e spegne la via PI3K-Akt"],a:4,s:"La sua perdita lascia Akt sempre attiva."},
{t:"b6c",k:"m",q:"Quale tipo di recettore produce la risposta più rapida (millisecondi)?",o:["il recettore nucleare degli ormoni steroidei", "il recettore accoppiato a un canale ionico (per esempio il nicotinico)", "il recettore tirosin-chinasico", "il recettore accoppiato a proteina G", "il recettore citosolico dei glucocorticoidi"],a:1,s:"Il ligando apre direttamente il canale; tipico delle sinapsi."},
{t:"b6c",k:"m",q:"La tossina del colera blocca l'attività GTPasica di Gαs. Conseguenza negli enterociti:",o:["il cAMP scende quasi a zero", "si bloccano i canali del Na⁺", "si attiva la caspasi 3", "il cAMP resta alto, escono Cl⁻ e acqua: diarrea grave", "aumenta l'IP₃ e il Ca²⁺ resta nel reticolo"],a:3,s:"Gαs non riesce più a spegnersi."},
{t:"b6c",k:"m",q:"Quale di questi è un oncogene che deriva da un componente della trasduzione del segnale?",o:["HER2 amplificato nel tumore della mammella", "p53", "Rb", "PTEN", "BRCA1"],a:0,s:"Gli altri sono oncosoppressori."},
{t:"b6c",k:"m",q:"Perché un solo ormone legato a un GPCR può produrre migliaia di molecole di cAMP?",o:["perché l'ormone si moltiplica nel citosol", "perché il cAMP si autoreplica", "perché il recettore attiva molte proteine G e ogni adenilato ciclasi produce molte molecole di cAMP", "perché il recettore sintetizza direttamente cAMP", "perché l'ormone viene endocitato e copiato"],a:2,s:"È l'amplificazione a cascata."},
{t:"b6c",k:"c",q:"Le proteine G trimeriche sono formate dalle subunità α, β e ____.",a:["GAMMA", "Γ"],s:"α lega il GTP; βγ restano unite tra loro."},
{t:"b6c",k:"c",q:"L'ossido nitrico attiva la guanilato ciclasi solubile e fa aumentare il ____ (sigla).",a:["CGMP", "GMPC", "GMP CICLICO"],s:"Il cGMP rilassa la muscolatura liscia dei vasi."},
{t:"b6c",k:"c",q:"Nella via Ras-MAP chinasi la GEF che attiva Ras, reclutata dall'adattatore Grb2, si chiama ____.",a:["SOS"],s:"Fa scambiare GDP con GTP su Ras."},
{t:"b6c",k:"c",q:"Quando una cellula risponde al segnale che lei stessa ha prodotto si parla di segnalazione ____.",a:["AUTOCRINA"],s:"Frequente nei linfociti e nelle cellule tumorali."},
{t:"b7a",k:"m",q:"Quale complesso ciclina-CDK guida l'ingresso in mitosi?",o:["ciclina D-CDK4", "ciclina E-CDK2", "ciclina A-CDK2", "ciclina B-CDK1", "ciclina D-CDK6"],a:3,s:"È il fattore che promuove la mitosi (MPF)."},
{t:"b7a",k:"m",q:"La fosfatasi Cdc25 favorisce l'ingresso in mitosi perché:",o:["fosforila Rb", "degrada la ciclina B", "attiva p53", "lega E2F", "rimuove i fosfati inibitori aggiunti da Wee1 su CDK1"],a:4,s:"L'attivazione di CDK1 è così improvvisa e irreversibile."},
{t:"b7a",k:"m",q:"p21 e p27 appartengono alla famiglia di inibitori delle CDK:",o:["Cip/Kip, che inibiscono diversi complessi ciclina-CDK", "INK4, che inibiscono solo CDK4/6", "delle fosfatasi mitotiche", "delle ubiquitina ligasi", "delle cicline di G1"],a:0,s:"p16 appartiene invece alla famiglia INK4."},
{t:"b7a",k:"m",q:"Una cellula in G1 a cui si tolgono i fattori di crescita DOPO il punto di restrizione:",o:["torna subito in G0", "va in apoptosi", "completa comunque il ciclo", "si blocca in G2", "replica il DNA due volte"],a:2,s:"Superato il punto di restrizione, Rb resta fosforilata ed E2F attivo."},
{t:"b7a",k:"m",q:"Che cosa fa MDM2?",o:["fosforila Rb", "ubiquitina p53 e ne promuove la degradazione", "attiva E2F", "ripara il DNA", "inibisce Bcl-2"],a:1,s:"Il danno al DNA fa fosforilare p53, che sfugge a MDM2 e si accumula."},
{t:"b7a",k:"m",q:"Nella sindrome di Li-Fraumeni si eredita un allele mutato di TP53. Perché i tumori compaiono presto e in molti organi?",o:["perché p53 è un oncogene dominante", "perché in ogni cellula basta un secondo «colpo» sull'altro allele", "perché TP53 è codificato dal DNA mitocondriale", "perché il gene si trova sul cromosoma Y", "perché la mutazione è soltanto epigenetica"],a:1,s:"Modello dei due colpi di Knudson per gli oncosoppressori."},
{t:"b7a",k:"m",q:"Gli oncogeni dei retrovirus, come v-src:",o:["sono geni oncosoppressori virali", "sono rRNA virali", "non hanno alcun corrispettivo nelle cellule", "codificano caspasi", "sono versioni alterate di proto-oncogeni cellulari catturate dal virus"],a:4,s:"Così si è scoperto il proto-oncogene cellulare c-src."},
{t:"b7a",k:"m",q:"Il checkpoint G2/M impedisce l'ingresso in mitosi se:",o:["i cromosomi non sono attaccati al fuso", "manca la ciclina D", "il DNA non è stato replicato completamente o è danneggiato", "la cellula ha appena superato il punto di restrizione", "la membrana ha perso le caderine"],a:2,s:"Il controllo dell'attacco al fuso avviene invece in metafase."},
{t:"b7a",k:"m",q:"Quale virus è associato al tumore del collo dell'utero tramite proteine che inattivano p53 e Rb?",o:["papillomavirus umano (HPV) ad alto rischio", "virus dell'influenza", "rinovirus", "virus del morbillo", "virus della varicella-zoster"],a:0,s:"E6 fa degradare p53, E7 lega Rb."},
{t:"b7a",k:"c",q:"Il fattore di trascrizione trattenuto da Rb non fosforilata si chiama ____.",a:["E2F"],s:"Accende i geni per la fase S."},
{t:"b7a",k:"c",q:"La chinasi CAK attiva le CDK aggiungendo un gruppo ____ su una treonina del loro segmento di attivazione.",a:["FOSFATO", "FOSFORICO"],s:"È una fosforilazione attivante, diversa da quelle inibitorie di Wee1."},
{t:"b7a",k:"c",q:"Lo stato di quiescenza, fuori dal ciclo, in cui si trovano molte cellule differenziate si indica con la sigla ____.",a:["G0","GO","G ZERO","G 0","G-ZERO"],s:"Alcune cellule (epatociti) possono rientrare nel ciclo."},
{t:"b7b",k:"m",q:"I microtubuli che si irradiano dai poli verso la corteccia cellulare e orientano il fuso sono:",o:["del cinetocore", "interpolari", "dell'assonema", "astrali", "del corpo basale"],a:3,s:"La dineina ancorata alla corteccia li tira."},
{t:"b7b",k:"m",q:"Nei microtubuli interpolari la chinesina-5 fa scorrere i microtubuli antiparalleli l'uno sull'altro. Che cosa provoca?",o:["l'allontanamento dei poli e l'allungamento del fuso (anafase B)", "la condensazione dei cromosomi", "l'attacco dei microtubuli ai cinetocori", "la rottura della lamina nucleare", "la formazione del solco di divisione"],a:0,s:"Inibitori della chinesina-5 producono fusi monopolari."},
{t:"b7b",k:"m",q:"La disgregazione della lamina nucleare all'inizio della mitosi è dovuta a:",o:["degradazione delle lamine nei lisosomi", "taglio delle lamine da parte delle caspasi", "depolimerizzazione dell'actina", "fosforilazione delle lamine da parte di CDK1", "azione della separasi"],a:3,s:"In telofase le lamine vengono defosforilate e la lamina si riforma."},
{t:"b7b",k:"m",q:"Durante la mitosi l'apparato di Golgi:",o:["resta intatto e passa a una sola figlia", "si frammenta in vescicole che vengono distribuite alle due cellule figlie", "si fonde con il nucleo", "si trasforma in reticolo ruvido", "forma l'anello contrattile"],a:1,s:"Si ricompone dopo la divisione."},
{t:"b7b",k:"m",q:"Il checkpoint del fuso blocca l'anafase inibendo:",o:["la ciclina D", "la coesina", "Cdc20, l'attivatore dell'APC/C", "la telomerasi", "Ras"],a:2,s:"Finché anche un solo cinetocore non è attaccato."},
{t:"b7b",k:"m",q:"Perché la degradazione della ciclina B è necessaria per uscire dalla mitosi?",o:["perché la ciclina B taglia la coesina", "perché serve a replicare il DNA", "perché attiva p53", "perché forma il fuso", "perché l'attività di CDK1 deve calare per riformare l'involucro, decondensare i cromosomi e fare la citodieresi"],a:4,s:"Una ciclina B non degradabile blocca la cellula in mitosi."},
{t:"b7b",k:"m",q:"Nella mitosi asimmetrica di una cellula staminale:",o:["le due cellule figlie ricevono determinanti diversi e hanno destini diversi", "le figlie hanno un numero diverso di cromosomi", "non avviene la citodieresi", "si separano i cromosomi omologhi", "si formano gameti aploidi"],a:0,s:"Una figlia resta staminale, l'altra si differenzia."},
{t:"b7b",k:"m",q:"Nell'anafase A:",o:["il fuso si allunga per scorrimento dei microtubuli interpolari", "i microtubuli del cinetocore si accorciano e i cromatidi si muovono verso i poli", "si forma il solco di divisione", "la cromatina si decondensa", "il DNA si replica"],a:1,s:"L'anafase B è l'allungamento del fuso."},
{t:"b7b",k:"c",q:"Il complesso del cinetocore che lega direttamente i microtubuli si chiama ____ (sigla).",a:["NDC80", "NDC 80"],s:"Resta attaccato anche mentre il microtubulo si allunga o si accorcia."},
{t:"b7b",k:"c",q:"La proteina che inibisce la separasi fino all'anafase si chiama ____.",a:["SECURINA"],s:"Viene ubiquitinata dall'APC/C."},
{t:"b7b",k:"c",q:"Il complesso proteico ad anello che tiene uniti i cromatidi fratelli fino all'anafase è la ____.",a:["COESINA"],s:"Viene tagliata dalla separasi."},
{t:"b7b",k:"c",q:"L'ubiquitina ligasi che avvia l'anafase si chiama APC/C o ____.",a:["CICLOSOMA"],s:"Degrada securina e ciclina B."},
{t:"b7c",k:"m",q:"Una non disgiunzione nella meiosi I produce:",o:["due gameti normali e due anomali", "solo gameti normali", "quattro gameti anomali: due con un cromosoma in più e due con uno in meno", "gameti triploidi", "un gamete anomalo e tre normali"],a:2,s:"In meiosi II invece due gameti sono normali, uno n+1 e uno n−1."},
{t:"b7c",k:"m",q:"Quale evento della meiosi NON avviene nella mitosi?",o:["la condensazione dei cromosomi", "la formazione del fuso", "la separazione dei cromatidi fratelli", "l'appaiamento degli omologhi con il crossing over", "la citodieresi"],a:3,s:"Avviene in profase I."},
{t:"b7c",k:"m",q:"Quante combinazioni diverse di cromosomi può produrre un essere umano solo per assortimento indipendente degli omologhi?",o:["23", "46", "23²", "2⁴⁶", "2²³, circa 8,4 milioni"],a:4,s:"Ogni coppia di omologhi si orienta a caso in metafase I."},
{t:"b7c",k:"m",q:"Quando completa la meiosi II l'ovocita umano?",o:["alla nascita", "all'inizio della pubertà", "a ogni ciclo, prima dell'ovulazione", "solo dopo la fecondazione da parte dello spermatozoo", "mai"],a:3,s:"Fino ad allora resta fermo in metafase II."},
{t:"b7c",k:"m",q:"Una cellula staminale pluripotente:",o:["può originare anche la placenta", "origina un solo tipo cellulare", "può originare tutti i tipi cellulari dell'embrione, ma non gli annessi extraembrionali", "non si divide mai", "è un gamete aploide"],a:2,s:"Totipotente è solo lo zigote (con i primi blastomeri)."},
{t:"b7c",k:"m",q:"Le cellule staminali emopoietiche del midollo osseo sono:",o:["totipotenti", "multipotenti", "unipotenti", "pluripotenti indotte", "aploidi"],a:1,s:"Danno tutte le cellule del sangue, ma non altri tessuti."},
{t:"b7c",k:"m",q:"Le iPS (staminali pluripotenti indotte) si ottengono:",o:["prelevandole dalla blastocisti", "isolandole dal midollo osseo", "dai gameti maturi", "fondendo due ovociti", "riprogrammando cellule adulte con pochi fattori di trascrizione (Oct4, Sox2, Klf4, c-Myc)"],a:4,s:"Sono pluripotenti come le staminali embrionali."},
{t:"b7c",k:"m",q:"Una bambina 45,X (Turner) è daltonica come il padre; la madre ha visione normale e non è portatrice. Qual è la spiegazione più probabile?",o:["l'ovocita era privo di cromosoma X per una non disgiunzione materna", "non disgiunzione nella meiosi I del padre", "non disgiunzione nella meiosi II del padre", "non disgiunzione in entrambi i genitori", "una mutazione nuova nel cromosoma Y"],a:0,s:"Il suo unico X, con l'allele del daltonismo, viene dal padre."},
{t:"b7c",k:"c",q:"I punti in cui i cromatidi non fratelli degli omologhi restano uniti dopo il crossing over si chiamano ____.",a:["CHIASMI", "CHIASMA"],s:"Visibili dal diplotene."},
{t:"b7c",k:"c",q:"La struttura proteica che tiene appaiati gli omologhi in profase I si chiama complesso ____.",a:["SINAPTONEMALE"],s:"Si forma nello zigotene e si smonta nel diplotene."},
{t:"b7c",k:"c",q:"Nella spermatogenesi la cellula aploide che si trasforma in spermatozoo senza più dividersi si chiama ____.",a:["SPERMATIDE", "SPERMATIDIO"],s:"Il differenziamento si chiama spermiogenesi."},
{t:"b7d",k:"m",q:"Il complesso DISC della via estrinseca è formato da:",o:["citocromo c, Apaf-1 e caspasi 9", "Bax e Bak", "p53 e p21", "recettore di morte (per esempio Fas), FADD e procaspasi 8", "APC/C e Cdc20"],a:3,s:"Le procaspasi 8 avvicinate si attivano a vicenda."},
{t:"b7d",k:"m",q:"La MOMP consiste in:",o:["la rottura della membrana plasmatica nella necrosi", "la permeabilizzazione della membrana mitocondriale esterna da parte di Bax e Bak", "l'apertura dei pori nucleari", "la fusione dei mitocondri", "la fosforilazione di Rb"],a:1,s:"Permette l'uscita del citocromo c."},
{t:"b7d",k:"m",q:"La proteina Bid collega la via estrinseca a quella intrinseca perché:",o:["lega direttamente il citocromo c", "inibisce l'apoptosoma", "tagliata dalla caspasi 8 (tBid) attiva Bax e Bak sul mitocondrio", "è un recettore di morte", "degrada Bcl-2 nel nucleo"],a:2,s:"Amplifica il segnale dei recettori di morte."},
{t:"b7d",k:"m",q:"Quale proteina, liberata dal mitocondrio insieme al citocromo c, neutralizza gli inibitori delle caspasi (IAP)?",o:["Bcl-xL", "FADD", "FasL", "MDM2", "Smac/DIABLO"],a:4,s:"Così le caspasi attivate non vengono più frenate."},
{t:"b7d",k:"m",q:"Le caspasi esecutrici, come la caspasi 3:",o:["sono attivate per taglio dalle iniziatrici e tagliano centinaia di proteine, come le lamine", "attivano le caspasi iniziatrici", "sono sintetizzate solo quando inizia l'apoptosi", "agiscono fuori dalla cellula", "sono tirosin-chinasi"],a:0,s:"Sono già presenti come procaspasi inattive."},
{t:"b7d",k:"m",q:"Il venetoclax, usato in alcune leucemie:",o:["inibisce Bcl-2 e favorisce l'apoptosi delle cellule tumorali", "attiva Bcl-2", "blocca la caspasi 3", "inibisce p53", "provoca necrosi delle cellule sane"],a:0,s:"Libera Bax e Bak dal freno di Bcl-2."},
{t:"b7d",k:"m",q:"Il recettore TNF-R1, a differenza di Fas, spesso:",o:["attiva direttamente la caspasi 9", "funziona come canale ionico", "attiva prima NF-κB e geni di sopravvivenza, e induce la morte solo se questa via è bloccata", "entra nel nucleo come fattore di trascrizione", "fosforila Rb"],a:2,s:"Lo stesso ligando può quindi avere effetti opposti."},
{t:"b7d",k:"c",q:"La proteina adattatrice che collega Fas alla procaspasi 8 si indica con la sigla ____.",a:["FADD"],s:"Fa parte del DISC."},
{t:"b7d",k:"c",q:"Nella via intrinseca il citocromo c si lega alla proteina ____ formando l'apoptosoma.",a:["APAF-1", "APAF1", "APAF"],s:"L'apoptosoma attiva la caspasi 9."},
{t:"b7d",k:"c",q:"Il taglio del DNA tra i nucleosomi nell'apoptosi dà all'elettroforesi una caratteristica «____» di frammenti multipli di circa 200 bp.",a:["SCALETTA", "SCALA"],s:"Nella necrosi il DNA si degrada in modo casuale (strisciata)."}
);
BIO_PT.push(
P("b5","b5a","Se metti un globulo rosso in acqua distillata, che cosa succede?",["si raggrinzisce","resta uguale","si gonfia e può scoppiare","diventa più rigido senza cambiare volume","si divide in due"],2,"L'acqua entra per osmosi verso la soluzione più concentrata, cioè il citoplasma, e la cellula si gonfia fino a rompersi.",["Si raggrinzisce in una soluzione più concentrata (ipertonica), non in acqua pura.","Resterebbe uguale solo in una soluzione isotonica.","","Il volume cambia proprio perché entra acqua.","L'osmosi sposta acqua, non fa dividere la cellula."]),
P("b5","b5e","Il reticolo endoplasmatico ruvido si chiama così perché:",["contiene DNA","è rivestito di cellulosa","ha pori come il nucleo","è pieno di granuli di amido","ha ribosomi attaccati sulla superficie"],4,"I ribosomi legati alla membrana, che sintetizzano proteine da secernere o di membrana, gli danno l'aspetto granuloso.",["Il DNA si trova nel nucleo e nei mitocondri, non nel reticolo.","La cellulosa forma la parete delle cellule vegetali, fuori dalla membrana.","I pori sono una caratteristica dell'involucro nucleare.","L'amido è una riserva delle piante, nei plastidi.",""]),
P("b6","b6c","Un ormone agisce solo su alcune cellule, dette bersaglio, perché:",["solo quelle ricevono sangue","l'ormone è troppo grande per entrare nelle altre","le altre cellule lo distruggono subito","solo quelle hanno il recettore specifico","solo quelle hanno il nucleo"],3,"La risposta richiede un recettore che riconosca l'ormone; le cellule senza recettore lo «ignorano».",["Quasi tutte le cellule sono raggiunte dal sangue.","Molti ormoni agiscono senza entrare nella cellula, legandosi a recettori di membrana.","Gli ormoni vengono degradati, ma non in modo selettivo dalle sole cellule non bersaglio.","","Quasi tutte le cellule del corpo hanno il nucleo."]),
P("b6","b6c","Tra due neuroni il segnale passa attraverso la sinapsi grazie a:",["ormoni trasportati dal sangue","neurotrasmettitori liberati nello spazio sinaptico","il passaggio di DNA","anticorpi","la parete cellulare"],1,"Il neurone presinaptico libera neurotrasmettitori che si legano ai recettori del neurone successivo (segnalazione sinaptica).",["Gli ormoni nel sangue sono la segnalazione endocrina, più lenta e a distanza.","","Il DNA non passa tra le cellule.","Gli anticorpi servono alla difesa immunitaria.","Le cellule animali non hanno parete."]),
P("b7","b7c","Quanti cromosomi ha uno spermatozoo umano?",["46","92","22","23","24"],3,"I gameti sono aploidi: 22 autosomi più un cromosoma sessuale (X o Y).",["46 è il numero delle cellule somatiche diploidi.","92 cromatidi si contano in una cellula diploide dopo la replicazione.","22 sono solo gli autosomi: manca il cromosoma sessuale.","","24 si avrebbe con un cromosoma in più (non disgiunzione)."]),
P("b7","b7c","Le cellule staminali sono cellule:",["che non si dividono mai","già completamente specializzate","capaci di dividersi rinnovandosi e di dare origine a cellule specializzate","presenti solo nel sangue","prive di nucleo"],2,"Hanno due proprietà: autorinnovamento e capacità di differenziarsi.",["Al contrario, si dividono per tutta la vita dell'organismo.","Sono proprio le cellule non ancora specializzate.","","Si trovano in molti tessuti (pelle, intestino, midollo).","Hanno il nucleo con tutto il DNA."])
);
BIO_TOPICS.find(t=>t.id==="b5a").sp.push("Il glicocalice è lo strato di catene di zuccheri (oligosaccaridi di glicoproteine e glicolipidi, e proteoglicani) che ricopre la faccia esterna della membrana plasmatica. Protegge la superficie da danni meccanici e chimici e trattiene acqua; essendo ricco di acido sialico dà alla cellula una carica negativa che riduce le adesioni indesiderate, per esempio tra globuli rossi. Soprattutto serve al riconoscimento: gli antigeni del sistema AB0 sono zuccheri del glicocalice, le selectine dei leucociti riconoscono zuccheri sull'endotelio e molti virus e batteri si agganciano a zuccheri di superficie. Gli zuccheri stanno sempre sul lato non citosolico perché vengono aggiunti nel lume del reticolo e del Golgi.",
 "L'asimmetria della membrana nasce già nel reticolo e nel Golgi ed è mantenuta attivamente. Le flippasi (ATPasi) riportano fosfatidilserina e fosfatidiletanolammina nel foglietto interno consumando ATP, le floppasi spostano lipidi verso l'esterno, le scramblasi (attivate dal Ca²⁺ o dalle caspasi) rimescolano i due foglietti. Il passaggio spontaneo di un fosfolipide da un foglietto all'altro (flip-flop) è rarissimo, mentre il movimento laterale è velocissimo. Anche le proteine hanno un orientamento fisso, deciso quando vengono inserite nel reticolo, che non cambia più.",
 "L'osmosi è il passaggio di acqua attraverso una membrana semipermeabile dalla soluzione con meno soluti a quella con più soluti. In soluzione isotonica una cellula animale non cambia volume; in soluzione ipotonica (acqua distillata) acquista acqua, si gonfia e può rompersi (emolisi dei globuli rossi); in soluzione ipertonica perde acqua e raggrinzisce. Le cellule animali non hanno parete e regolano il volume spostando ioni con pompe e trasportatori, seguiti dall'acqua attraverso le acquaporine. Per questo le soluzioni per infusione endovenosa sono isotoniche (soluzione fisiologica, NaCl 0,9%).");
BIO_TOPICS.find(t=>t.id==="b5b").sp.push("Anche i recettori degli ormoni steroidei usano l'importazione regolata. Il recettore dei glucocorticoidi, senza ormone, resta nel citosol legato a un complesso di chaperon (Hsp90) che ne nasconde la NLS. Il cortisolo attraversa la membrana e si lega al recettore: il complesso si scioglie, la NLS viene esposta e le importine portano il recettore nel nucleo, dove si lega come dimero alle sequenze di risposta agli ormoni e regola la trascrizione. Mascherare o esporre una NLS (recettori steroidei, NF-κB) o liberare un frammento da una membrana (SREBP1) sono modi con cui la cellula decide quando un fattore di trascrizione può agire.",
 "Anche gli RNA escono dal nucleo attraverso i pori, sempre legati a proteine (ribonucleoproteine). Gli mRNA maturi, con cappuccio, coda di poli-A e introni rimossi, sono riconosciuti dal recettore di esportazione NXF1 (TAP), che interagisce direttamente con le ripetizioni FG: questa via non usa Ran. Un mRNA che contiene ancora introni viene trattenuto: è un controllo di qualità. tRNA, precursori dei microRNA, snRNA e subunità ribosomiali escono invece con esportine dipendenti da Ran-GTP (per esempio CRM1, l'esportina-t per i tRNA, l'esportina 5 per i pre-miRNA).",
 "Oltre al nucleolo, il nucleo contiene altri condensati senza membrana, formati per separazione di fase di proteine e RNA: i corpi di Cajal (maturazione degli snRNA), gli speckle (depositi di fattori di splicing), i corpi PML. Il nucleolo si organizza attorno ai geni ripetuti degli rRNA (regioni NOR), assembla le subunità ribosomiali con proteine importate dal citosol, scompare in mitosi e si riforma in telofase. Dal punto di vista topologico lo spazio tra le due membrane nucleari è continuo con il lume del reticolo, e i lumi di reticolo, Golgi, endosomi e lisosomi sono equivalenti all'esterno della cellula; il nucleo invece è in continuità con il citosol attraverso i pori.");
BIO_TOPICS.find(t=>t.id==="b5c").sp.push("Il flusso dell'informazione nei mitocondri ha regole proprie. Il mtDNA ha una regione regolatoria (ansa D) da cui partono replicazione e trascrizione; entrambi i filamenti vengono trascritti in lunghi RNA policistronici, poi tagliati dove si trovano i tRNA, posti tra un gene e l'altro come una «punteggiatura». Gli mRNA non hanno introni né cappuccio e sono tradotti da ribosomi mitocondriali simili a quelli batterici con un codice leggermente diverso (per esempio UGA codifica triptofano). Gli enzimi che replicano, trascrivono e traducono il mtDNA (come la DNA polimerasi γ) sono però codificati dal nucleo e importati. Ogni cellula contiene centinaia o migliaia di copie di mtDNA: se coesistono copie normali e mutate (eteroplasmia), la malattia compare solo sopra una certa soglia.",
 "La glicolisi ha una fase di investimento (si spendono 2 ATP; la fosfofruttochinasi-1 è il principale punto di regolazione) e una di rendimento (4 ATP e 2 NADH): netto 2 ATP. Senza ossigeno il piruvato viene ridotto a lattato per rigenerare il NAD⁺ e far continuare la glicolisi. Con l'ossigeno la piruvato deidrogenasi e il ciclo di Krebs liberano in tutto 6 CO₂ per glucosio. L'ATP sintasi ha una parte nella membrana interna (F₀), un rotore fatto girare dal flusso dei protoni, e una parte nella matrice (F₁) che sintetizza ATP; servono circa 4 protoni per ogni ATP prodotto ed esportato, perciò un NADH vale circa 2,5 ATP e un FADH₂ circa 1,5. Il conto: 2 ATP (glicolisi) + 2 GTP (Krebs) + 10 NADH × 2,5 + 2 FADH₂ × 1,5 = 32, cioè circa 30–32 ATP per glucosio a seconda di come il NADH citosolico entra nel mitocondrio.",
 "I mitocondri formano una rete dinamica che cambia forma di continuo. La fusione unisce prima le membrane esterne (mitofusine MFN1 e MFN2) e poi le interne (OPA1), mescolando contenuti e mtDNA: un mitocondrio danneggiato può così essere compensato dai vicini. La fissione è eseguita dalla GTPasi DRP1, reclutata dal citosol sulla membrana esterna, spesso nei punti di contatto con il reticolo, che la strozza come un anello. La fissione distribuisce i mitocondri alle cellule figlie e isola le parti danneggiate da eliminare con la mitofagia. Mutazioni di MFN2 e OPA1 causano malattie neurologiche (una forma di Charcot-Marie-Tooth e l'atrofia ottica dominante).");
BIO_TOPICS.find(t=>t.id==="b5d").sp.push("Le proteine della matrice dei perossisomi, sintetizzate su ribosomi liberi, sono riconosciute nel citosol da recettori solubili: PEX5 lega il segnale PTS1 (SKL al C-terminale), PEX7 il segnale PTS2 (vicino all'N-terminale). Il recettore carico si aggancia a un complesso di attracco sulla membrana (PEX13, PEX14), entra con il carico, lo rilascia nella matrice e torna nel citosol grazie all'ubiquitinazione e alle ATPasi PEX1 e PEX6. Le proteine possono entrare già ripiegate e perfino come oligomeri, cosa impossibile per mitocondri e reticolo. Le proteine della membrana perossisomiale seguono un'altra via: PEX19 le lega nel citosol e le consegna a PEX3 sulla membrana.",
 "Le malattie perossisomali si dividono in difetti di biogenesi (mutazioni dei geni PEX: spettro di Zellweger, con perossisomi «fantasma» privi di enzimi) e difetti di un singolo enzima o trasportatore (come l'adrenoleucodistrofia legata all'X). Nella sindrome di Zellweger, la forma più grave, i neonati presentano ipotonia, convulsioni, alterazioni del cranio e del volto, fegato ingrossato e cisti renali. Nel sangue sono alti gli acidi grassi a catena molto lunga, mentre mancano i plasmalogeni, necessari alla mielina.");
BIO_TOPICS.find(t=>t.id==="b5e").sp.push("Il ripiegamento è assistito da chaperon in ogni fase. Nel citosol le catene nascenti escono dal ribosoma protette da chaperon come Hsp70, che impediscono interazioni sbagliate e mantengono srotolate le proteine destinate ai mitocondri finché non raggiungono TOM e TIM; le chaperonine (TRiC nel citosol, Hsp60 nel mitocondrio) offrono una camera chiusa in cui ripiegarsi. Nel lume del reticolo la chaperon principale è BiP (famiglia Hsp70), che lega le catene appena uscite dal traslocone, mentre la disolfuro isomerasi (PDI) forma i ponti disolfuro corretti.",
 "Il ciclo calnexina/calreticulina funziona così. L'oligosaccaride trasferito dal dolicolo sull'asparagina (14 zuccheri) termina con tre glucosi; le glucosidasi I e II ne tolgono due e la glicoproteina con un solo glucosio viene legata da calnexina o calreticulina. Quando anche l'ultimo glucosio viene rimosso la proteina è libera; se non è ancora ripiegata bene, l'enzima sensore UGGT le riaggiunge un glucosio e il ciclo ricomincia. Se il ripiegamento fallisce più volte, la rimozione di mannosi la indirizza all'ERAD. Esempio classico sono le immunoglobuline: nelle plasmacellule le catene pesanti restano nel reticolo, legate a BiP e alle lectine chaperon, finché non si uniscono alle catene leggere; escono solo anticorpi completi.",
 "Le proteine residenti del reticolo (BiP, PDI) hanno al C-terminale la sequenza KDEL: se sfuggono verso il Golgi, il recettore di KDEL nella rete cis le riconosce e le riporta indietro con vescicole COPI. Tra reticolo e Golgi si trovano il compartimento intermedio (ERGIC) e la rete cis del Golgi, che ricevono le vescicole COPII e smistano il carico. Nella risposta UPR, PERK blocca gran parte della traduzione fosforilando eIF2α, IRE1 attiva il fattore di trascrizione XBP1 con uno splicing non convenzionale del suo mRNA, ATF6 viene tagliato nel Golgi e il frammento va nel nucleo: aumentano chaperon e componenti dell'ERAD. Se lo stress non si risolve, la UPR attiva l'apoptosi (per esempio tramite il fattore CHOP).");
BIO_TOPICS.find(t=>t.id==="b5f").sp.push("L'endocitosi in fase fluida (pinocitosi) ingloba in modo non selettivo liquido extracellulare con i soluti disciolti: avviene con piccole vescicole, con le caveole (invaginazioni ricche di caveolina e colesterolo) e con la macropinocitosi, in cui grandi pieghe di membrana guidate dall'actina racchiudono gocce di liquido. L'endocitosi mediata da recettori è invece selettiva: i recettori carichi vengono raccolti dagli adattatori AP2 in fossette rivestite di clatrina, e il ligando può essere concentrato di oltre mille volte rispetto alla fase fluida. Transferrina, LDL ed EGF entrano tutti così, ma il loro destino è diverso: la transferrina e il suo recettore tornano in superficie, l'LDL va al lisosoma mentre il recettore viene riciclato, il recettore dell'EGF viene degradato insieme al ligando.",
 "Le vescicole endocitiche si fondono con gli endosomi precoci di smistamento (Rab5, PI3P), alla periferia, con pH di circa 6–6,5: qui molti ligandi si staccano dai recettori. I recettori da riutilizzare tornano in membrana direttamente o attraverso gli endosomi di riciclo (Rab11). Ciò che va degradato resta nell'endosoma, che matura in endosoma tardivo (Rab7, pH più acido) e diventa un corpo multivescicolare: le proteine di membrana ubiquitinate, come il recettore dell'EGF, vengono sequestrate dai complessi ESCRT in vescicole che gemmano verso l'interno. Infine l'endosoma tardivo si fonde con i lisosomi (pH circa 5) e il contenuto viene digerito.",
 "Nelle cellule polarizzate, come gli enterociti, la membrana apicale e quella basolaterale (separate dalle giunzioni occludenti) hanno ciascuna i propri endosomi precoci, che confluiscono in un endosoma di riciclo comune dove le proteine vengono smistate verso il lato giusto. La transcitosi sfrutta questo sistema: il recettore delle immunoglobuline polimeriche lega le IgA sul lato basolaterale, le trasporta attraverso la cellula e sul lato apicale viene tagliato, liberando nel lume le IgA secretorie con un pezzo del recettore (componente secretoria). Nel neonato le IgG del latte materno attraversano l'epitelio intestinale nel verso opposto grazie al recettore FcRn, che le lega a pH acido.",
 "Le tappe finali del traffico sono attracco (tethering), ormeggio (docking) e fusione. Le Rab-GTP sulla vescicola reclutano effettori, lunghe proteine filamentose o grandi complessi, che agganciano la vescicola alla membrana giusta; poi le SNARE si appaiano e, avvolgendosi a fascio, avvicinano i doppi strati fino a fonderli; NSF e SNAP separano poi i complessi SNARE. I fosfoinositidi sono un «codice di indirizzo» lipidico: chinasi e fosfatasi specifiche producono PI(4,5)P₂ nella membrana plasmatica, PI4P nel Golgi, PI3P negli endosomi precoci e PI(3,5)P₂ in quelli tardivi, e molte proteine di rivestimento e di attracco riconoscono il fosfoinositide giusto.",
 "Le malattie da accumulo lisosomiale sono per lo più recessive e colpiscono soprattutto i neuroni, che non si dividono e non possono «diluire» il materiale accumulato: Tay-Sachs (esosaminidasi A, accumulo del ganglioside GM2), Gaucher (glucocerebrosidasi), Pompe (α-glucosidasi acida, glicogeno nei lisosomi del muscolo). Anche le alterazioni dell'autofagia hanno conseguenze gravi: nelle malattie neurodegenerative (Parkinson, Huntington, Alzheimer) aggregati proteici e mitocondri danneggiati non vengono smaltiti. Nella mitofagia la chinasi PINK1 si accumula sui mitocondri depolarizzati e recluta l'ubiquitina ligasi Parkin, ed entrambe sono mutate in forme familiari di Parkinson. L'autofagia difende anche dai batteri intracellulari e nei tumori ha un ruolo doppio: ostacola la trasformazione ma aiuta le cellule tumorali a sopravvivere allo stress.");
BIO_TOPICS.find(t=>t.id==="b5g").sp.push("La nucleazione dei microtubuli è il passo lento e richiede un innesco: il complesso ad anello della γ-tubulina (γTuRC), una sagoma da cui cresce il microtubulo con l'estremità − ancorata. Nelle cellule animali il γTuRC è concentrato nel materiale pericentriolare del centrosoma, che circonda una coppia di centrioli (nove triplette di microtubuli disposte a cilindro). Il centrosoma si duplica una sola volta per ciclo, in fase S, così che in mitosi ci siano due poli. Le MAP si dividono in non motrici (tau e MAP2, che stabilizzano e distanziano i microtubuli; proteine che seguono l'estremità + in crescita) e motrici (chinesine e dineine).",
 "La dineina citoplasmatica, con il complesso attivatore dinattina, trasporta verso il centro della cellula endosomi, lisosomi e vescicole, mantiene il Golgi vicino al centrosoma e, nei neuroni, porta carichi dalle terminazioni al corpo cellulare (trasporto retrogrado); in mitosi posiziona il fuso. Le sue alterazioni colpiscono soprattutto il sistema nervoso: mutazioni di LIS1, regolatore della dineina, causano la lissencefalia (corteccia liscia perché i neuroni migrano male durante lo sviluppo), e difetti della dineina o della dinattina causano malattie del motoneurone e neuropatie. Le chinesine fanno il trasporto anterogrado lungo l'assone.",
 "Ciglia e flagelli crescono da un corpo basale, un centriolo modificato. Nelle ciglia mobili l'assonema 9+2 si piega perché le braccia di dineina di ogni doppietta camminano sulla doppietta vicina, mentre i collegamenti di nexina impediscono lo scorrimento libero e lo trasformano in flessione. Le ciglia primarie (9+0), presenti su quasi tutte le cellule, non si muovono ma fanno da antenna per segnali chimici e meccanici. Nella discinesia ciliare primaria (sindrome di Kartagener) le dineine dell'assonema sono difettose: muco non rimosso e infezioni respiratorie, spermatozoi immobili e, in circa metà dei casi, situs inversus, perché nell'embrione le ciglia del nodo decidono la lateralità degli organi.",
 "L'actina-G lega ATP e si aggiunge soprattutto all'estremità + (barbed); nel filamento l'ATP viene idrolizzato ad ADP, che rende i monomeri più facili da staccare all'estremità −. In condizioni stazionarie un filamento può aggiungere monomeri al + e perderli al − mantenendo la lunghezza costante (treadmilling). Le proteine accessorie regolano ogni tappa: la profilina consegna actina-ATP all'estremità +, la timosina sequestra i monomeri, la cofilina taglia i filamenti vecchi, le proteine di cappuccio bloccano le estremità; il complesso Arp2/3, attivato da proteine della famiglia WASP, nuclea nuovi filamenti a 70° sul fianco di quelli esistenti. Filamina e α-actinina uniscono i filamenti in reti o fasci.",
 "Nel sarcomero, l'unità contrattile del muscolo striato compresa tra due linee Z, i filamenti sottili di actina sono ancorati alle linee Z e quelli spessi di miosina II stanno al centro (banda A). Le teste della miosina, idrolizzando ATP, tirano l'actina verso il centro: i filamenti non si accorciano ma scorrono, banda I e zona H si restringono e le linee Z si avvicinano. Tropomiosina e troponina bloccano l'interazione finché il Ca²⁺ non viene liberato dal reticolo sarcoplasmatico. La distrofina, sotto la membrana, collega l'actina al complesso del distroglicano, che lega la laminina della matrice: senza di essa la membrana si lacera a ogni contrazione.",
 "La migrazione richiede polarità. Un neutrofilo che percepisce un gradiente di peptidi batterici (come fMLP) attraverso recettori accoppiati a proteine G attiva la PI3K sul lato rivolto verso la sorgente: il PIP₃ prodotto richiama GEF che accendono Rac e Cdc42, che con Arp2/3 spingono avanti un ampio lamellipodio. Al retro domina Rho, che tramite la chinasi ROCK attiva la miosina II e contrae la coda, staccandola dal substrato. Il fronte avanza, nuove adesioni si formano davanti e quelle posteriori si sciolgono: così la cellula risale il gradiente fino al focolaio d'infezione (chemiotassi).",
 "I filamenti intermedi si formano da monomeri con un lungo dominio centrale ad α-elica: due monomeri si avvolgono in un dimero coiled-coil parallelo, due dimeri si affiancano in modo antiparallelo in un tetramero, e otto tetrameri formano un'unità che si allunga fino al filamento da 10 nm. Poiché i tetrameri sono antiparalleli il filamento non è polare e non può essere percorso da motori. È flessibile ma resiste alla trazione: senza cheratine funzionanti (epidermolisi bollosa semplice) la pelle si rompe per piccoli traumi. I diversi elementi del citoscheletro sono collegati da proteine ponte come la plectina; il complesso LINC (nesprine nella membrana nucleare esterna, proteine SUN in quella interna) unisce il citoscheletro alla lamina nucleare e alla cromatina, collegando nucleoscheletro e citoscheletro e trasmettendo forze meccaniche fino al nucleo.");
BIO_TOPICS.find(t=>t.id==="b6a").sp.push("Le integrine collegano la matrice al citoscheletro nelle adesioni focali: all'interno talina e vinculina le legano all'actina, mentre la chinasi FAK e altre proteine trasmettono segnali di sopravvivenza e proliferazione. Le integrine possono essere attivate dall'interno (inside-out, per esempio nei leucociti e nelle piastrine) o trasmettere segnali dall'esterno (outside-in). La meccanotrasduzione è la trasformazione di forze in segnali biochimici: su una matrice rigida la cellula tira di più con l'actomiosina, le adesioni focali crescono e fattori come YAP/TAZ entrano nel nucleo accendendo geni di proliferazione; su una matrice morbida avviene il contrario. Molte cellule normali hanno bisogno di ancoraggio per dividersi e sopravvivere (se si staccano vanno in apoptosi, chiamata anoikis), mentre le cellule tumorali perdono questa dipendenza.",
 "La fibronectina circola anche nel plasma in forma solubile; nei tessuti viene assemblata in fibrille solo quando le cellule, legandola con le integrine, la stirano con la tensione del citoscheletro: lo stiramento espone siti nascosti che permettono alle molecole di unirsi tra loro. La rete di fibronectina guida poi la deposizione del collagene e la migrazione delle cellule nell'embrione e nella guarigione delle ferite. Il collagene fibrillare (tipo I) è una tripla elica di catene con la sequenza ripetuta Gly-X-Y, ricca di prolina e idrossiprolina; l'idrossilazione richiede vitamina C, la cui carenza causa lo scorbuto.");
BIO_TOPICS.find(t=>t.id==="b6b").sp.push("Le molecole di adesione permettono alle cellule di riconoscersi e di organizzarsi in tessuti. Poiché le caderine legano preferibilmente caderine dello stesso tipo, cellule che esprimono caderine diverse (E-caderina negli epiteli, N-caderina nei neuroni) si separano spontaneamente in gruppi: è il meccanismo con cui, nell'embrione, foglietti e organi si separano. Il cambio del tipo di caderina accompagna la transizione epitelio-mesenchima, nello sviluppo e nella progressione dei tumori. Le giunzioni non sono solo «colla»: le giunzioni aderenti trasmettono tensione e segnali (la β-catenina è anche un effettore della via Wnt), e le giunzioni comunicanti coordinano il comportamento di gruppi di cellule.");
BIO_TOPICS.find(t=>t.id==="b6c").sp.push("Le proteine G monomeriche (piccole GTPasi: Ras, Rho, Rab, Ran, Arf) sono interruttori come la subunità α delle proteine trimeriche: accese con GTP, spente con GDP. Due tipi di proteine regolatorie le controllano: le GEF le accendono facendo uscire il GDP ed entrare il GTP (più abbondante nel citosol); le GAP le spengono accelerando l'idrolisi del GTP. Per questo la perdita di una GAP equivale a un'attivazione: nella neurofibromatosi di tipo 1 manca la neurofibromina, una GAP di Ras, e Ras resta attivo più a lungo. Le proteine G trimeriche (α, β, γ) sono attivate dai recettori GPCR, che fanno loro da GEF.",
 "Ogni tappa della cascata moltiplica il segnale: un recettore attivato attiva molte proteine G, ogni enzima effettore produce migliaia di molecole di secondo messaggero, ogni chinasi fosforila molti bersagli. Nella visione una sola rodopsina eccitata da un fotone attiva centinaia di transducine e fa idrolizzare moltissime molecole di cGMP: un bastoncello può rispondere a un singolo fotone. Il segnale deve anche spegnersi: la rodopsina attivata è fosforilata dalla rodopsina chinasi e legata dall'arrestina, la transducina idrolizza il suo GTP e il calo di Ca²⁺ riattiva la guanilato ciclasi. Con luce intensa e prolungata questi meccanismi riducono la sensibilità (adattamento alla luce): è un esempio di desensitizzazione. Per gli altri GPCR le chinasi GRK e le β-arrestine fanno lo stesso e possono portare il recettore all'endocitosi.",
 "Il recettore dell'EGF è un monomero che dimerizza quando lega il fattore di crescita; le tirosine fosforilate reclutano Grb2-SOS e attivano la via Ras-MAP chinasi verso la proliferazione; dopo il legame il recettore viene endocitato e in gran parte degradato nei lisosomi, il che spegne il segnale. Il recettore dell'insulina è invece già un dimero α₂β₂ unito da ponti disolfuro: l'insulina ne cambia la conformazione e attiva le chinasi delle subunità β, che fosforilano le proteine IRS (substrati del recettore dell'insulina). Da IRS parte soprattutto la via PI3K → PIP₃ → Akt, che porta GLUT4 in membrana nel muscolo e nel tessuto adiposo e stimola la sintesi di glicogeno e proteine; in misura minore si attiva anche la via Ras-MAP chinasi.",
 "I fosfoinositidi sono fosfolipidi del foglietto interno fosforilabili sull'inositolo. Il PI(4,5)P₂ è il punto di partenza di due vie: la fosfolipasi C (attivata da Gq o da alcuni recettori tirosin-chinasici) lo taglia in IP₃ e DAG; la PI3K lo fosforila in posizione 3 producendo PIP₃, che richiama in membrana proteine con domini PH come Akt e la chinasi PDK1 che la attiva. La fosfatasi PTEN toglie il fosfato in posizione 3 e spegne la via: è un oncosoppressore spesso perso nei tumori. Molti oncogeni sono componenti delle vie di segnalazione resi sempre attivi: fattori di crescita prodotti in eccesso, recettori amplificati o mutati (HER2, EGFR), Ras che non idrolizza il GTP, chinasi come BRAF V600E o la proteina di fusione BCR-ABL della leucemia mieloide cronica, fattori di trascrizione come Myc.");
BIO_TOPICS.find(t=>t.id==="b7a").sp.push("L'attività delle CDK è modulata in più modi oltre al legame con la ciclina. La chinasi CAK aggiunge un fosfato attivante; la chinasi Wee1 aggiunge fosfati inibitori, che la fosfatasi Cdc25 rimuove, attivando di colpo la ciclina B-CDK1 all'ingresso in mitosi. Gli inibitori delle CDK sono di due famiglie: INK4 (come p16), che bloccano solo CDK4/6, e Cip/Kip (p21, p27, p57), che inibiscono più complessi. Infine le cicline vengono distrutte al momento giusto per ubiquitinazione e proteasoma: la ligasi SCF agisce soprattutto al passaggio G1/S, l'APC/C in mitosi (ciclina B, securina). La degradazione rende il ciclo unidirezionale.",
 "I virus oncogeni sono coinvolti in circa il 10–15% dei tumori umani. I virus a DNA (papillomavirus ad alto rischio, virus di Epstein-Barr, virus dell'epatite B, herpesvirus del sarcoma di Kaposi) producono proteine che spingono la cellula a replicarsi: E6 di HPV fa degradare p53 ed E7 lega Rb liberando E2F. I retrovirus possono portare un oncogene, versione alterata di un proto-oncogene cellulare «catturato» (v-src del virus del sarcoma di Rous, che ha fatto scoprire il c-src cellulare), oppure attivare un proto-oncogene inserendosi vicino a esso; nell'uomo il retrovirus HTLV-1 causa una leucemia a cellule T. Le infezioni croniche da virus dell'epatite B e C favoriscono il tumore del fegato anche attraverso l'infiammazione.");
BIO_TOPICS.find(t=>t.id==="b7b").sp.push("L'ingresso in mitosi è innescato dalla ciclina B-CDK1 (fattore che promuove la mitosi, MPF), attivata di colpo quando Cdc25 rimuove i fosfati inibitori: un circuito a retroazione positiva rende il passaggio rapido e irreversibile. CDK1 fosforila centinaia di bersagli: le condensine (condensazione dei cromosomi), le lamine (la lamina si depolimerizza e l'involucro si frammenta o viene assorbito nel reticolo), le nucleoporine (smontaggio dei pori) e le proteine che regolano i microtubuli, che diventano più corti e dinamici. Anche gli organelli cambiano: il Golgi si frammenta in vescicole e il reticolo si riorganizza, così che entrambe le figlie ne ricevano una parte; sintesi proteica e traffico vescicolare rallentano.",
 "Il fuso mitotico ha tre tipi di microtubuli, tutti con l'estremità − verso i poli: quelli del cinetocore, legati ai cinetocori dal complesso NDC80, che resta agganciato alla punta anche mentre questa si allunga o si accorcia; quelli interpolari, che si sovrappongono all'equatore con estremità + antiparallele; quelli astrali, che si irradiano verso la corteccia. I meccanoenzimi del fuso sono motori: la chinesina-5 fa scorrere i microtubuli interpolari spingendo i poli lontano; la dineina ancorata alla corteccia tira i microtubuli astrali e posiziona il fuso; le cromochinesine spingono i bracci dei cromosomi verso l'equatore; chinesine depolimerizzanti accorciano i microtubuli. Un attacco corretto mette i cinetocori fratelli sotto tensione; gli attacchi sbagliati, senza tensione, vengono staccati (dalla chinasi Aurora B) e ritentati.");
BIO_TOPICS.find(t=>t.id==="b7c").sp.push("Le aneuploidie nascono per lo più da errori della meiosi. Se la non disgiunzione avviene in meiosi I (gli omologhi migrano insieme), tutti e quattro i gameti sono anomali: due n+1 e due n−1. Se avviene in meiosi II (i cromatidi fratelli non si separano), due gameti sono normali, uno n+1 e uno n−1. Il rischio cresce con l'età materna soprattutto perché la coesione tra cromatidi negli ovociti, fermi in profase I da decenni, si indebolisce e i bivalenti con pochi chiasmi si separano male. La fecondazione di un gamete n+1 dà una trisomia, quella di un gamete n−1 una monosomia; errori nelle mitosi dopo la fecondazione producono invece mosaici, con linee cellulari normali e anomale.",
 "Una cellula staminale ha due proprietà: l'autorinnovamento (dividendosi produce almeno una cellula staminale uguale a sé) e la capacità di dare cellule differenziate. Ci riesce con divisioni asimmetriche, che producono una figlia staminale e una destinata a differenziarsi, oppure, a livello di popolazione, con divisioni simmetriche bilanciate. Nell'adulto le staminali vivono in nicchie che ne controllano l'attività (midollo osseo, base delle cripte intestinali, strato basale dell'epidermide, testicolo). Gli spermatogoni sono staminali della linea germinale che permettono di produrre spermatozoi per tutta la vita, mentre nella donna la riserva di ovociti è fissata prima della nascita.");
BIO_TOPICS.find(t=>t.id==="b7d").sp.push("Via estrinseca nel dettaglio: i ligandi di morte (FasL, TNF, TRAIL) sono trimeri e raggruppano tre recettori; il dominio di morte citoplasmatico dei recettori recluta l'adattatore FADD, che lega più molecole di procaspasi 8, formando il DISC (complesso di segnalazione che induce la morte). Le procaspasi avvicinate si attivano a vicenda tagliandosi (attivazione per prossimità) e la caspasi 8 attiva le esecutrici; in alcune cellule il segnale deve essere amplificato dal mitocondrio tramite il taglio di Bid. La proteina c-FLIP, simile alla caspasi 8 ma inattiva, può bloccare il DISC. Il recettore TNF-R1 in genere attiva prima NF-κB, che accende geni di sopravvivenza e infiammazione, e induce la morte solo se questa via è bloccata.",
 "Nella via intrinseca il citocromo c, che normalmente nello spazio intermembrana trasporta elettroni nella catena respiratoria, esce con la MOMP insieme ad altre proteine come Smac/DIABLO, che neutralizza le IAP (inibitori delle caspasi). Nel citosol il citocromo c lega Apaf-1, che con dATP si assembla in una struttura a ruota a sette raggi, l'apoptosoma, che recluta e attiva la caspasi 9 e quindi la 3. Le caspasi esecutrici tagliano centinaia di proteine: le lamine (il nucleo si frammenta), l'inibitore di una DNasi che poi taglia il DNA tra i nucleosomi (all'elettroforesi una «scaletta» di frammenti multipli di circa 200 bp), proteine del citoscheletro; attivano inoltre le scramblasi che espongono la fosfatidilserina.");
